void table(const std::filesystem::path& p,const Array& rows){std::set<std::string> keys;for(const auto& v:rows)for(const auto& kv:v.as_object())keys.insert(std::string(kv.key()));if(rows.empty()){write_table(p,{"status","reason"},Array{Object{{"status","UNAVAILABLE"},{"reason","NO_QUALIFYING_OBSERVATIONS"}}});return;}write_table(p,{keys.begin(),keys.end()},rows);}
Array numbers(const std::vector<std::int64_t>& v){Array a;for(auto n:v)a.push_back(n);return a;}
