std::string state_key(const Frame& f,const std::vector<std::size_t>& indices){std::string key;for(auto i:indices){const auto& e=f.books[i].book->evidence;key+=field(std::to_string(e.content_hash))+field(std::to_string(e.connection_epoch));}return key;}
